// Actual original video-option commands, including video-only target filtering.
use filmcraft_project::*;use filmcraft_time::{Tick,TimeRange,FrameRate};use serde_json::{json,Value};use sha2::{Digest,Sha256};
fn main()->Result<(),Box<dyn std::error::Error>>{
 let mut s=filmcraft_engine::Session::default();s.execute("file.openDemoProject",json!({}))?;let sequence=s.state.active_sequence.unwrap();let p=std::sync::Arc::make_mut(&mut s.project);
 let media=p.items.values().find(|i|i.as_media().is_some_and(|m|m.info.has_video())).unwrap().id;
 {let m=p.item_mut(media).unwrap().as_media_mut().unwrap();m.interpret.frame_rate=Some(FrameRate::FPS_29_97);m.info.start_timecode=Some(1000);}
 let graphic=p.add_item("Graphic",Label::Blue,ItemKind::Graphic{width:320,height:240,rate:FrameRate::FPS_25},None);
 let sub=p.add_item("Subclip",Label::Rose,ItemKind::Subclip{parent:media,range:TimeRange::new(Tick(100),Tick(100000000000)),restrict_trims:true},None);
 let q=p.sequence_mut(sequence).unwrap();let first=q.video_tracks[0].items[0].id;let second=q.video_tracks[1].items[0].id;let audio=q.audio_tracks[0].items[0].id;
 q.video_tracks[0].locked=true;q.video_tracks[0].items[0].link=Some(777);q.audio_tracks[0].items[0].link=Some(777);
 for t in q.video_tracks.iter_mut().chain(q.audio_tracks.iter_mut()){for c in &mut t.items{c.source_in=Tick(200000000000);c.speed=1.25;c.frame_hold=Some(Tick(7));c.hold_filters=true;c.scale_to_frame=true;c.field_options=Some(FieldOptions{reverse_field_dominance:true,processing:FieldProcessing::FlickerRemoval});c.time_interpolation=TimeInterpolation::OpticalFlow;for e in &mut c.effects{for p in e.params.values_mut(){p.keyframes.push(keyframe::Keyframe::new(Tick(10),p.value.clone()));}}}}
 let base=s.project.clone();let mut profiles=vec![];
 for profile in 0..4{let mut p=base.clone();let q=std::sync::Arc::make_mut(&mut p).sequence_mut(sequence).unwrap();if profile==1{q.video_tracks[0].items[0].reverse=true;q.video_tracks[0].items[0].speed=-0.75;q.video_tracks[1].items[0].item=graphic;}if profile==2{q.video_tracks[0].items[0].effects.retain(|e|e.effect!="motion");q.video_tracks[1].items[0].item=ItemId(u64::MAX);}if profile==3{q.video_tracks[0].items[0].item=sub;q.video_tracks[0].items[0].speed=0.;}profiles.push(p);}
 let choices:Vec<Value>=vec![json!({}),json!({"clips":[first.0]}),json!({"clips":[first.0,first.0,audio.0,second.0,999999]}),json!({"clips":[]}),json!({"clip":second.0}),json!({"clips":[999999]}),json!({"clips":[audio.0]}),json!({"enabled":false,"holdOn":"invalid","holdFilters":true}),json!({"holdOn":"in"}),json!({"holdOn":"out","holdFilters":true}),json!({"holdOn":"playhead"}),json!({"holdOn":"sequenceTime","time":1000000000000_i64}),json!({"holdOn":"sequenceTime","frame":-10}),json!({"holdOn":"sequenceTime","seconds":0.5}),json!({"holdOn":"sequenceTime","timecode":"00:00:03:00"}),json!({"holdOn":"sequenceTime","timecode":"bad"}),json!({"holdOn":"sourceTimecode","time":123456789000_i64}),json!({"holdOn":"sourceTimecode","timecode":"00:01:00:00","time":7}),json!({"holdOn":"sourceTimecode","timecode":"bad","time":7}),json!({"holdOn":"sourceTimecode"}),json!({"holdOn":"unknown"}),json!({"processing":"alwaysDeinterlace","reverseFieldDominance":true}),json!({"processing":"flickerRemoval"}),json!({"processing":"unknown"}),json!({"processing":false,"holdOn":false,"enabled":"ignored"}),json!({"mode":"frameSampling"}),json!({"mode":"FRAME BLENDING"}),json!({"mode":"opticalFlow"}),json!({"mode":"unknown"})];
 let commands=["clip.frameHoldOptions","clip.fieldOptions","clip.timeInterpolation.frameSampling","clip.timeInterpolation.frameBlending","clip.timeInterpolation.opticalFlow","clip.setTimeInterpolation","clip.fitToFrame","clip.fillFrame"];
 let mut cases=vec![];for(pi,project)in profiles.iter().enumerate(){for state in 0..6{for command in commands{for params in &choices{
 s.project=project.clone();s.history.undo.clear();s.history.redo.clear();s.state.active_sequence=if state==5{None}else{Some(sequence)};s.state.selection=match state{0=>vec![],1=>vec![first],2=>vec![audio],3=>vec![ClipId(999999)],4=>vec![second],_=>vec![first]};s.state.linked_selection=true;s.state.playheads.insert(sequence,Tick(100000000000));let context=json!({"activeSequence":s.state.active_sequence,"selection":s.state.selection,"linkedSelection":true,"playhead":s.playhead().0});let r=s.execute(command,params.clone());let after=serde_json::to_value(s.project.as_ref())?;
 cases.push(json!({"profile":pi,"command":command,"params":params,"context":context,"ok":r.is_ok(),"result":r.ok(),"afterSha256":format!("{:x}",Sha256::digest(serde_json::to_vec(&after)?)),"undo":s.history.undo.len()}));
 }}}}
 let projects:Vec<_>=profiles.iter().map(|p|p.as_ref()).collect();std::fs::write(std::env::args().nth(1).ok_or("output required")?,serde_json::to_vec(&json!({"sourceCommit":"5231852443363f001c3f6b396dd9b1e6461ae2be","projects":projects,"cases":cases}))?)?;Ok(())
}
